from mk import *
STRICT["on"] = True
import math

def fig():
    g = Fig(560, 260, "קשת וחץ בגובה 1.8 מטר מעל הקרקע, ותפוח באותו גובה במרחק 6 מטר")
    g.ground(40, 520, 220)
    g.path("M 100,58 Q 140,100 100,142", stroke="var(--d-line)", width=3)
    g.line(100, 58, 100, 142, width=1.2)
    g.arrow(100, 100, 150, 100, None)
    g.circle(440, 100, 9, fill="#c2410c"); g.line(440, 91, 440, 84, width=1.5)
    g.heb(440, 76, "תפוח"); g.heb(100, 46, "קשת"); g.heb(480, 240, "קרקע")
    g.dim(100, 100, 440, 100, "6 m", offset=40, side=-1)
    g.dim(300, 100, 300, 220, "1.8 m")
    g.line(150, 100, 430, 100, stroke="var(--d-dim)", width=1, dash="4 4")
    return g

E(id="bagrut-2004-q1", year=2004, label="2004 שאלה 1", topic="kinematics", sub="kin-projectile", diff=3, fig=fig,
  stem=r"חץ מונח בקשת דרוכה, ומכוון אופקית ימינה אל תפוח שמוחזק במנוחה. החץ והתפוח נמצאים בגובה $1.8\,\text{m}$ מעל הקרקע, והמרחק ביניהם $6\,\text{m}$. ברגע $t = 0$ יורים את החץ במהירות אופקית של $20\,\text{m/s}$, ובאותו רגע משחררים את התפוח ממנוחה. אפשר להזניח את השפעת האוויר, ולהתייחס לחץ ולתפוח כאל גופים נקודתיים.",
  parts=[
    P("א", r"הראו שהחץ עובר את המרחק האופקי עד התפוח לפני שהתפוח פוגע בקרקע.", OPEN, ["principle", "algebra"], [
        X(r"משווים שני זמנים: כמה זמן לוקח לחץ לעבור את המרחק האופקי, וכמה זמן לוקח לתפוח ליפול לקרקע. בוחרים את כיוון הירייה כחיובי בציר האופקי, וכלפי מטה כחיובי בציר האנכי. השאלה לא קבעה כיוונים."),
        S(r"הזמן של החץ עד התפוח", r"בציר האופקי לא פועל כוח, ולכן המהירות קבועה", r"6 = 0 + 20\,t_x \;\Rightarrow\; t_x = \frac{6}{20} = 0.3\,\text{s}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"זמן הנפילה של התפוח", r"התפוח יוצא ממנוחה, והתאוצה היא תאוצת הכובד, ולכן מציבים אותה במקום התאוצה", r"1.8 = 0 + 0 \cdot t + \tfrac{1}{2} \cdot 10\,t_y^2 \;\Rightarrow\; t_y^2 = 0.36 \;\Rightarrow\; t_y = 0.6\,\text{s}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"משווים", r"החץ מגיע למרחק של התפוח לפני שהתפוח מגיע לקרקע", r"0.3\,\text{s} < 0.6\,\text{s}"),
    ], r"החץ עובר את המרחק ב-$0.3\,\text{s}$, והתפוח נופל לקרקע רק אחרי $0.6\,\text{s}$"),
    P("ב", r"הסבירו מדוע החץ פוגע בתפוח. אפשר להסביר במילים או בנוסחאות.", OPEN, ["understanding", "principle"], [
        X(r"בציר האנכי, החץ והתפוח יוצאים באותו רגע, מאותו גובה, בלי מהירות אנכית, ובאותה תאוצה."),
        S(r"התנועה האנכית זהה", r"לשני הגופים אותה משוואת מקום בציר האנכי. נסמן את החץ באחת ואת התפוח בשתיים, ונמדוד גובה מהקרקע כלפי מעלה", r"y_1(t) = y_2(t) = 1.8 - 5t^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"מסקנה", r"בכל רגע הם באותו גובה. לכן כשהחץ מגיע למרחק האופקי של התפוח, הוא פוגע בו", r"t = 0.3\,\text{s}:\quad y_1 = y_2 = 1.8 - 0.45 = 1.35\,\text{m}"),
    ], r"התנועה האנכית של שניהם זהה, ולכן הם תמיד באותו גובה", key=r"הסבר"),
    P("ג", r"מה גודל המהירות של החץ ברגע הפגיעה בתפוח, ומה כיוונה ביחס לכיוון האופקי?", multi((r"גודל המהירות", math.hypot(20, 3), "m/s"), (r"הזווית מתחת לכיוון האופקי", math.degrees(math.atan(3 / 20)), "°")), ["principle", "algebra"], [
        S(r"הרכיב האנכי ברגע הפגיעה", r"החץ יוצא בלי מהירות אנכית, ונופל שלוש עשיריות שנייה בתאוצת הכובד", r"v_y = 0 + 10 \cdot 0.3 = 3\,\text{m/s}", eq=r"v = v_0 + at"),
        S(r"גודל המהירות לפי משפט פיתגורס", r"הרכיב האופקי לא השתנה, ושני הרכיבים ניצבים זה לזה", r"v = \sqrt{20^2 + 3^2} = \sqrt{409} \approx 20.2\,\text{m/s}"),
        S(r"הזווית עם האופק", r"הטנגנס של הזווית הוא הרכיב האנכי חלקי הרכיב האופקי", r"\tan\theta = \frac{3}{20} = 0.15 \;\Rightarrow\; \theta \approx 8.5^\circ"),
    ], r"$\approx 20.2\,\text{m/s}$, בזווית $\approx 8.5^\circ$ מתחת לכיוון האופקי", key=r"v≈20.2 m/s ; θ=8.5°"),
    P("ד", r"עכשיו הקשת יורה את החץ באלכסון מעל האופק, כך שהרכיב האופקי של מהירות החץ הוא $20\,\text{m/s}$, והרכיב האנכי $20\,\text{m/s}$ כלפי מעלה. ברגע הירייה זורקים את התפוח אנכית כלפי מעלה. באיזו מהירות צריך לזרוק את התפוח כדי שהחץ יפגע בו? נמקו.", num(20, "m/s"), ["principle", "understanding"], [
        X(r"כמו בסעיף ב: כדי שהחץ והתפוח יהיו תמיד באותו גובה, התנועה האנכית שלהם צריכה להיות זהה. כאן בוחרים כלפי מעלה כחיובי."),
        S(r"משוואות המקום בציר האנכי", r"שניהם יוצאים מאותו גובה, באותה תאוצה, שלילית כי היא כלפי מטה. ההבדל יכול להיות רק במהירות האנכית ההתחלתית", r"y_1 = 1.8 + 20t - 5t^2 \qquad y_2 = 1.8 + u\,t - 5t^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"התנאי לפגיעה", r"המשוואות זהות בכל רגע רק אם המהירויות האנכיות ההתחלתיות שוות", r"y_1 = y_2 \;\Rightarrow\; u = 20\,\text{m/s}"),
        C(r"בדיקה: התפוח עדיין באוויר כשהחץ מגיע", r"בציר האופקי החץ עדיין עובר את המרחק בשלוש עשיריות שנייה", r"y(0.3) = 1.8 + 6 - 0.45 = 7.35\,\text{m} > 0 \;\checkmark"),
    ], r"$20\,\text{m/s}$ כלפי מעלה", key=r"20 m/s"),
  ],
  concepts=["זריקה אופקית", "זריקה משופעת", "אי-תלות בין הצירים", "פגיעה במטרה נופלת"],
  summary=r"חץ ותפוח שנופל באותו רגע. בציר האנכי הם זהים, ולכן החץ תמיד פוגע, גם כשזורקים אותם למעלה.",
  note=r"שני גופים עם אותה מהירות אנכית התחלתית ובאותו גובה נשארים באותו גובה כל הזמן.",
  review="הנחה שלי.\nסעיף ג הוא סעיף אחד, כמו במקור, עם שתי תיבות: גודל וזווית.\nמה לבדוק: רק לאשר.")
